MATCH (source:PlantItem)-[:send_to*1..]->(target:PlantItem {tag: "P-45301A"})
WHERE NOT EXISTS {
  MATCH (:PlantItem)-[:send_to]->(source)
}
RETURN DISTINCT source.tag AS tag

MATCH (s:PlantItem {tag: 'P-51703'}), (t:PlantItem {tag: 'M-52401'})
RETURN s.tag AS source_tag, t.tag AS target_tag,
       EXISTS {
         MATCH p = (s)-[:send_to*1..]->(t)
         WHERE all(n IN nodes(p) WHERE n.tag IS NULL OR n.tag <> 'GTV-519001')
       } AS can_flow_without_valve

